<?php require_once __DIR__.'/../includes/functions.php';require_admin();$rows=db()->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();$pageTitle='Contact messages';include __DIR__.'/_header.php';?><div class="dash-top"><div><span class="eyebrow">Inbox</span><h1>Contact messages</h1><p>Messages submitted through the public contact form.</p></div></div><section class="dash-panel"><h2>Messages (<?=count($rows)?>)</h2><div class="table-wrap"><table class="admin-table"><thead><tr><th>Sender</th><th>Subject</th><th>Message</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['subject'])?></td><td class="message-cell"><?=e($r['message'])?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="4">No messages received yet.</td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__.'/_footer.php';?>